export const de = Object.assign(Object.fromEntries(Object.keys(en).map(key => [key, key])),bookMessages);
de["Show Spellbook Studio in sidebar"] = "Spellbook Studio in der Seitenleiste anzeigen";
export const catalogs = {en, de};
export function studioLanguage(hass) {
  const locale = String(hass?.locale?.language || hass?.language || "en").toLowerCase().replaceAll("_", "-");
  return catalogs[locale] ? locale : catalogs[locale.split("-")[0]] ? locale.split("-")[0] : "en";
}
export function translate(language, key, values = {}) {
  const message = catalogs[language]?.[key] || en[key] || key || "";
  return message.replace(/\{(\w+)\}/g, (match, name) => Object.hasOwn(values, name) ? String(values[name]) : match);
}

const englishKeys = new Map(Object.entries(en).map(([key, value]) => [value, key]));
const messagePatterns = Object.entries(en).filter(([key]) => /\{\w+\}/.test(key)).flatMap(([key, value]) =>
  [key, value].map(text => {
    const names = [];
    const pattern = text.split(/(\{\w+\})/).map(part => {
      if (/^\{\w+\}$/.test(part)) {names.push(part.slice(1,-1)); return "([\\s\\S]*?)";}
      return part.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    }).join("");
    return {key, names, pattern: new RegExp(`^${pattern}$`)};
  }));
export function translateMessage(language, text) {
  if (Object.hasOwn(en, text)) return translate(language, text);
  if (englishKeys.has(text)) return translate(language, englishKeys.get(text));
  for (const {key, names, pattern} of messagePatterns) {
    const match = String(text || "").match(pattern);
    if (match) return translate(language, key, Object.fromEntries(names.map((name, i) =>
      [name, ["state", "action"].includes(name) ? translateMessage(language, match[i+1]) : match[i+1]])));
  }
  return text || "";
}

// Book content is separate from interface translations. Preserve the chosen key when editing.
export function contentLanguage(value, language) {
  if (!value || typeof value !== "object") return undefined;
  return Object.keys(value).find(key => key.toLowerCase().replaceAll("_", "-") === language) ||
    Object.keys(value).find(key => key.toLowerCase().split(/[-_]/)[0] === language) ||
    (Object.hasOwn(value, "en") ? "en" : Object.keys(value)[0]);
}
export function localizedContent(value, language) {
  return value && typeof value === "object" ? value[contentLanguage(value, language)] || "" : value || "";
}
